<script lang="ts">
  // @ts-ignore: svelte-kit ambient path shims generated by prepare
  import { goto } from '$app/navigation';
  import { onMount } from 'svelte';
  import { ArrowLeft, RefreshCw, Inbox, Clock3, Check, ChevronLeft, Wand2, Activity, Zap } from '@lucide/svelte';
  import PredictorTeamSelect from './PredictorTeamSelect.svelte';
  import PredictorDateFilter, { type TimeBand } from './PredictorDateFilter.svelte';
  import PredictorStatusBanner from './PredictorStatusBanner.svelte';
  import PredictorMatchCard from './PredictorMatchCard.svelte';
  import PredictorVerdictPanel from './PredictorVerdictPanel.svelte';
  import PredictorSportIcon from './PredictorSportIcon.svelte';
  import { api, subscribeConvexQuery } from '$lib/convexClient';
  import {
    todayKey,
    dayKeyFor,
    dayBounds,
    fetchPredictorDay,
    fetchPredictorMatchesInRange,
    fetchPredictorDaysInRange,
    fetchPredictorVerdict,
    fetchActiveRun,
    startPredictorRefresh,
    analyzeCachedMatch,
    bootstrapTodayAllSports
  } from '$lib/predictorClient';
  import {
    DEFAULT_CONFIDENCE_FLOOR,
    type PredictorDay,
    type PredictorMatch,
    type PredictorRun,
    type PredictorSportId
  } from '$lib/predictorTypes';
  import { buildPredictorInsights } from '$lib/predictorInsights';
  import {
    PREDICTOR_MAX_SELECTIONS,
    clearSelection,
    loadSelection,
    saveSelection,
    toggleSelection
  } from '$lib/predictorSelections';
  import { AGENT_DEFS } from '$lib/agentUi';
  import type { Analysis, Pick } from '$lib/engine';

  let {
    sportId = null as PredictorSportId | null,
    accent = '#6366f1'
  }: {
    sportId?: PredictorSportId | null;
    accent?: string;
  } = $props();

  import { authState, canAccessPredictor } from '$lib/authStore.svelte';
  const predictorLocked = $derived(!canAccessPredictor(authState.user));

  import DailyPnlSummary from './DailyPnlSummary.svelte';
  import { generateGreatMindsDebate } from '$lib/greatMindsEngine';
  import type { GreatMindsDebateResult } from '$lib/predictorTypes';

  type Phase = 'select' | 'analyzing' | 'results';
  type SelectedAnalysis = {
    match: PredictorMatch;
    analysis: Analysis;
    qualifying: Pick[];
    insight?: Record<string, unknown> | null;
    greatMindsDebate?: GreatMindsDebateResult | null;
  };

  const activeSport = $derived(sportId);
  const effectiveSport = $derived(activeSport ?? ('football' as PredictorSportId));
  const today = $derived(todayKey());

  // Human-readable display name for each sport used in messages and toasts.
  const SPORT_DISPLAY_NAME: Record<PredictorSportId, string> = {
    football: 'Football', basketball: 'Basketball', tennis: 'Tennis',
    rally: 'Table Tennis', hockey: 'Ice Hockey', baseball: 'Baseball',
    americanfootball: 'American Football', rugby: 'Rugby', cricket: 'Cricket',
    mma: 'MMA', volleyball: 'Volleyball'
  };
  const sportDisplayName = $derived(SPORT_DISPLAY_NAME[effectiveSport] ?? effectiveSport);

  // Date window (defaults to today → +6 so the homepage shows up to 7 days where
  // cached data exists). Range is bounded to 7 days and clamped as the user picks.
  let fromDay = $state(dayKeyFor(0));
  let toDay = $state(dayKeyFor(6));
  let timeBand = $state<TimeBand>('all');

  type GameTab = 'upcoming' | 'inplay' | 'finished';
  const IN_PLAY_WINDOW_MS = 3 * 60 * 60 * 1000;
  let gameTab = $state<GameTab>('upcoming');

  let day = $state<PredictorDay | null>(null);
  let daysInRange = $state<PredictorDay[]>([]);
  let matches = $state<PredictorMatch[]>([]);
  let run = $state<PredictorRun | null>(null);
  let loading = $state(true);
  let busy = $state(false);
  let error = $state('');
  let now = $state(Date.now());
  let bootstrapping = $state(false);
  let bootstrapMsg = $state('');
  let bootstrapDone = $state(false);

  // ── Selection workflow state ─────────────────────────────────────────────────
  let phase = $state<Phase>('select');
  let selectedIds = $state<string[]>([]);
  let results = $state<SelectedAnalysis[]>([]);
  let agentProgress = $state(0);
  let agentStage = $state('');
  let selectNotice = $state('');
  let progressTimer: ReturnType<typeof setInterval> | null = null;
  let revealTimer: ReturnType<typeof setTimeout> | null = null;

  // ── Per-match cached verdict reveal (clicking a card shows only that match) ──
  let verdictCache = $state<Record<string, any | null>>({});
  let expandedMatches = $state<Record<string, boolean>>({});

  const insightFor = (m: PredictorMatch): ReturnType<typeof buildPredictorInsights> | null => {
    const hit = verdictCache[m.matchId];
    if (hit && typeof hit === 'object') return hit as ReturnType<typeof buildPredictorInsights>;
    // Fallback: build deterministic insight from cached engine picks so the card
    // always shows meaningful analysis when expanded (even before LLM verdict loads).
    const res = analyzeMatch(m);
    if (res.qualifying.length > 0) return buildPredictorInsights(m, res.qualifying);
    return null;
  };

  // Fetch and cache the stored LLM verdict for a specific match when its card expands.
  // Does NOT toggle expanded state — that is handled by the onClick caller.
  async function revealMatch(m: PredictorMatch) {
    if (verdictCache[m.matchId] !== undefined) return; // already fetched
    verdictCache = { ...verdictCache, [m.matchId]: null }; // mark as fetching
    try {
      const verdict = await fetchPredictorVerdict(m.dayKey || today, m.matchId);
      if (verdict?.aiReport && typeof verdict.aiReport === 'object') {
        verdictCache = { ...verdictCache, [m.matchId]: verdict.aiReport };
      }
    } catch (_) {
      /* leave null — card still shows deterministic picks/metrics */
    }
  }

  const isRunning = $derived(!!run && run.status === 'running');
  const refreshProgress = $derived(run?.progress ?? 0);
  const selectedSet = $derived(new Set(selectedIds));
  const isSelected = (id: string) => selectedSet.has(id);
  const qualifiedCount = $derived(results.filter((r) => r.qualifying.length > 0).length);
  const agentsRun = $derived(AGENT_DEFS.map((a) => a.name));
  const sourcesUsed = $derived(day?.sourcesUsed ?? []);
  const warnings = $derived(run?.message ? [run.message] : []);
  const runError = $derived(
    (run?.status === 'error' ? run.message || 'Agent refresh failed.' : '') ||
      (day?.status === 'error' ? day.message || 'Day cache refresh failed.' : '') ||
      ''
  );

  const filteredMatches = $derived.by(() => {
    if (timeBand === 'all') return matches;
    const band = timeBand;
    const bandHour = (ms: number) => new Date(ms).getUTCHours();
    return matches.filter((m) => {
      const h = bandHour(m.startTime);
      return band === 'morning' ? h < 12 : band === 'afternoon' ? h >= 12 && h < 18 : h >= 18;
    });
  });

  // Game status classification — pure client-side, no extra API calls.
  // Upcoming: not started. In-play: started within the 3h window. Finished:
  // ended more than 3h ago.
  const statusOf = (m: PredictorMatch): GameTab => {
    if (m.startTime <= 0) return 'upcoming';
    if (m.startTime > now) return 'upcoming';
    if (m.startTime > now - IN_PLAY_WINDOW_MS) return 'inplay';
    return 'finished';
  };

  const tabFilteredMatches = $derived.by(() => filteredMatches.filter((m) => statusOf(m) === gameTab));

  const tabCounts = $derived.by(() => {
    const counts: Record<GameTab, number> = { upcoming: 0, inplay: 0, finished: 0 };
    for (const m of filteredMatches) counts[statusOf(m)] += 1;
    return counts;
  });

  // Group the (time-band + tab-filtered) matches by their own cache day so the
  // page can show a 1–7 day window with each day's fixtures and status.
  const byDay = $derived.by(() => {
    const groups: Record<string, PredictorMatch[]> = {};
    for (const m of tabFilteredMatches) {
      const key = m.dayKey || today;
      (groups[key] ??= []).push(m);
    }
    return groups;
  });

  function groupByLeague(matchList: PredictorMatch[]): Record<string, PredictorMatch[]> {
    const groups: Record<string, PredictorMatch[]> = {};
    for (const m of matchList) {
      const lg = m.league || 'Other Leagues & Competitions';
      (groups[lg] ??= []).push(m);
    }
    return groups;
  }

  const dayMatchCount = $derived.by(() => {
    const map: Record<string, number> = {};
    for (const m of matches) map[m.dayKey || today] = (map[m.dayKey || today] ?? 0) + 1;
    return map;
  });

  const isPast = (m: PredictorMatch) => m.startTime > 0 && m.startTime < now;
  const dayHasData = $derived((dayKey: string) => daysInRange.some((d) => d.dayKey === dayKey && (d.status === 'ready' || d.status === 'partial')));

  // Ordered list of dayKeys in the selected window (bounded to 7 days).
  const windowDays = $derived.by(() => {
    const keys: string[] = [];
    let cur = fromDay;
    // up to 7 iterations; stops early when the window is exceeded
    for (let i = 0; i < 7; i++) {
      const bounds = dayBounds(cur);
      keys.push(cur);
      if (cur >= toDay) break;
      const next = new Date(bounds.to + 1);
      cur = next.toISOString().slice(0, 10);
    }
    return keys;
  });

  // ── Deterministic per-match screening (memoized) ─────────────────────────────
  const analysisCache = new Map<string, { analysis: any; qualifying: Pick[] }>();
  function analyzeMatch(match: PredictorMatch) {
    if (analysisCache.has(match.matchId)) return analysisCache.get(match.matchId)!;
    const res = analyzeCachedMatch(match, DEFAULT_CONFIDENCE_FLOOR);
    analysisCache.set(match.matchId, res);
    return res;
  }

  // ── Selection controls ────────────────────────────────────────────────────────
  function toggleMatch(match: PredictorMatch) {
    const dk = match.dayKey || today;
    const res = toggleSelection(effectiveSport, dk, match.matchId);
    selectedIds = res.selection;
    selectNotice = res.capped
      ? `You can analyse up to ${PREDICTOR_MAX_SELECTIONS} matches at a time. Deselect one first to pick this one.`
      : '';
  }

  function selectAll() {
    const eligible = filteredMatches.filter((m) => !isPast(m));
    const ids = eligible.slice(0, PREDICTOR_MAX_SELECTIONS).map((m) => m.matchId);
    selectedIds = ids;
    // Persist selections per day so switching windows keeps them.
    const byDk: Record<string, string[]> = {};
    for (const m of eligible.slice(0, PREDICTOR_MAX_SELECTIONS)) {
      const dk = m.dayKey || today;
      (byDk[dk] ??= []).push(m.matchId);
    }
    for (const [dk, idsList] of Object.entries(byDk)) saveSelection(effectiveSport, dk, idsList);
    selectNotice =
      eligible.length > PREDICTOR_MAX_SELECTIONS
        ? `Analysing the first ${PREDICTOR_MAX_SELECTIONS} matches. Deselect one to make room for another.`
        : '';
  }

  function clearAll() {
    selectedIds = [];
    const dks = new Set(matches.map((m) => m.dayKey || today));
    for (const dk of dks) clearSelection(effectiveSport, dk);
    selectNotice = '';
  }

  // ── Analysis run (deterministic compute + agent progression) ─────────────────
  function stageForPct(p: number): string {
    let acc = 0;
    for (const a of AGENT_DEFS) {
      acc += a.weight;
      if (p <= acc) return a.stage;
    }
    return 'Compiling verdicts';
  }

  function clearProgress() {
    if (progressTimer) {
      clearInterval(progressTimer);
      progressTimer = null;
    }
    if (revealTimer) {
      clearTimeout(revealTimer);
      revealTimer = null;
    }
  }

  function animateAgents() {
    clearProgress();
    const start = Date.now();
    const DURATION = 3600;
    progressTimer = setInterval(() => {
      const pct = Math.min(100, Math.round(((Date.now() - start) / DURATION) * 100));
      agentProgress = pct;
      agentStage = stageForPct(pct);
      if (pct >= 100) {
        clearProgress();
        revealTimer = setTimeout(() => {
          phase = 'results';
        }, 220);
      }
    }, 120);
  }

  function analyzeSelected() {
    const sid = effectiveSport;
    if (!sid) return;
    const selected = matches.filter((m) => selectedIds.includes(m.matchId));
    if (selected.length === 0) return;
    results = selected.map((m) => {
      const res = analyzeMatch(m);
      const greatMindsDebate = generateGreatMindsDebate(m, res.analysis);
      return { match: m, analysis: res.analysis, qualifying: res.qualifying, insight: null, greatMindsDebate };
    });
    phase = 'analyzing';
    agentProgress = 0;
    agentStage = AGENT_DEFS[0]?.stage ?? 'Fixtures fetched';
    animateAgents();
    enrichWithLlmVerdicts(selected);
  }

  // Surface the stored LLM (Agnes/OpenRouter) verdict for each selected match
  // when the cache has one; otherwise the deterministic insights render.
  async function enrichWithLlmVerdicts(selected: PredictorMatch[]) {
    const entries = await Promise.all(
      selected.map(async (m) => {
        let llmInsight: Record<string, unknown> | null = null;
        try {
          const verdict = await fetchPredictorVerdict(m.dayKey || today, m.matchId);
          if (verdict?.aiReport && typeof verdict.aiReport === 'object') {
            llmInsight = verdict.aiReport;
          }
        } catch (_) {
          /* ignore — fall back to deterministic insights */
        }
        return { matchId: m.matchId, llmInsight };
      })
    );
    results = results.map((r) => {
      const hit = entries.find((e) => e.matchId === r.match.matchId);
      return hit?.llmInsight ? { ...r, insight: hit.llmInsight } : r;
    });
  }

  function backToSelection() {
    clearProgress();
    phase = 'select';
  }

  function dayKeyLabel(key: string): string {
    const [y, m, d] = key.split('-').map(Number);
    if (!y || !m || !d) return key;
    return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString(undefined, {
      weekday: 'short',
      month: 'short',
      day: 'numeric'
    });
  }

  function groupByLeague(list: PredictorMatch[]): Record<string, PredictorMatch[]> {
    const groups: Record<string, PredictorMatch[]> = {};
    for (const m of list) {
      const k = m.league || 'Other';
      (groups[k] ??= []).push(m);
    }
    return groups;
  }

  async function refreshDay(dk: string) {
    const sid = effectiveSport;
    if (!sid || busy) return;
    busy = true;
    error = '';
    try {
      await startPredictorRefresh(sid, dk, true);
    } catch (err: any) {
      error = String(err?.message || err);
    } finally {
      busy = false;
    }
  }

  // ── Data loading + live subscriptions (reacts to sport/window changes) ───────
  let unsubs: (() => void)[] = [];
  let sportEpoch = 0;

  function disposeSubs() {
    unsubs.forEach((u) => u());
    unsubs = [];
  }

  async function loadRange(sid: PredictorSportId, fromDayArg: string, toDayArg: string, epoch: number) {
    loading = true;
    error = '';
    const [d, windowMatches, daysAll, r] = await Promise.all([
      fetchPredictorDay(sid, today).catch(() => null),
      fetchPredictorMatchesInRange(sid, fromDayArg, toDayArg).catch(() => []),
      fetchPredictorDaysInRange(sid, fromDayArg, toDayArg).catch(() => []),
      fetchActiveRun(sid, fromDayArg).catch(() => null)
    ]);
    if (epoch !== sportEpoch) return; // stale response after a switch
    day = d;
    matches = windowMatches;
    daysInRange = daysAll;
    run = r;
    // Prune stored selections that no longer appear in the window (per day).
    const kept: string[] = [];
    for (const m of windowMatches) {
      if (loadSelection(effectiveSport, m.dayKey || today).includes(m.matchId)) kept.push(m.matchId);
    }
    selectedIds = kept;
    loading = false;

    // Auto-bootstrap: if today has no cached data and nothing is running,
    // trigger a single-sport seed for the active sport. This ensures
    // first-time visitors see data without manually clicking 'Run agents'.
    if (epoch === sportEpoch && !d && windowMatches.length === 0 && !r && !bootstrapping && !bootstrapDone) {
      void autoSeedCurrentSport(sid, fromDayArg);
    }
  }

  // Seed just the currently-viewed sport (lighter than bootstrapping all 11).
  async function autoSeedCurrentSport(sid: PredictorSportId, dayKey: string) {
    if (busy || bootstrapping) return;
    bootstrapping = true;
    const displayName = SPORT_DISPLAY_NAME[sid] ?? sid;
    bootstrapMsg = `Loading ${displayName} matches for today…`;
    try {
      await startPredictorRefresh(sid, dayKey, false);
      bootstrapMsg = `AI agents running for ${displayName}. Data will appear shortly.`;
      bootstrapDone = true;
    } catch (err: any) {
      // Silently swallow — user can still click 'Run agents now'
      console.warn('[autoSeed]', err?.message || err);
    } finally {
      bootstrapping = false;
    }
  }

  // Bootstrap all 11 sports — triggered from empty-state CTA.
  async function runBootstrapAll() {
    if (busy || bootstrapping) return;
    bootstrapping = true;
    bootstrapMsg = 'Starting AI agents for all 11 sports — this takes a few minutes…';
    try {
      const res = await bootstrapTodayAllSports();
      bootstrapMsg = res.message || 'AI agents dispatched for all sports. Data will appear shortly.';
      bootstrapDone = true;
    } catch (err: any) {
      error = String(err?.message || err);
      bootstrapMsg = '';
    } finally {
      bootstrapping = false;
    }
  }

  function subscribe(sid: PredictorSportId, fromDayArg: string, toDayArg: string, epoch: number) {
    void subscribeConvexQuery<PredictorRun | null>(api.predictor.getActiveRun, { sportId: sid, dayKey: fromDayArg }, (r) => {
      if (r && epoch === sportEpoch) run = r;
    }).then((u) => {
      if (epoch === sportEpoch) unsubs.push(u);
      else u();
    });
    void subscribeConvexQuery<PredictorDay | null>(api.predictor.getDay, { sportId: sid, dayKey: today }, (d) => {
      if (d && epoch === sportEpoch) day = d;
    }).then((u) => {
      if (epoch === sportEpoch) unsubs.push(u);
      else u();
    });
    void subscribeConvexQuery<PredictorDay[]>(api.predictor.listDaysInRange, { sportId: sid, fromDay: fromDayArg, toDay: toDayArg }, (d) => {
      if (Array.isArray(d) && epoch === sportEpoch) daysInRange = d;
    }).then((u) => {
      if (epoch === sportEpoch) unsubs.push(u);
      else u();
    });
    void subscribeConvexQuery<PredictorMatch[]>(api.predictor.listMatchesInRange, { sportId: sid, fromDay: fromDayArg, toDay: toDayArg }, (m) => {
      if (Array.isArray(m) && epoch === sportEpoch) matches = m;
    }).then((u) => {
      if (epoch === sportEpoch) unsubs.push(u);
      else u();
    });
  }

$effect(() => {
    const sid = effectiveSport;
    if (!sid) return;
    // Slip the window (clamp to 7 days) so a reopened picker stays fresh.
    if (toDay < fromDay) toDay = fromDay;
    const fj = fromDay;
    const tj = toDay;
    sportEpoch += 1;
    const epoch = sportEpoch;
    clearProgress();
    phase = 'select';
    gameTab = 'upcoming';
    timeBand = 'all';
    results = [];
    selectNotice = '';
    disposeSubs();
    void loadRange(sid, fj, tj, epoch);
    subscribe(sid, fj, tj, epoch);
  });

  onMount(() => {
    const timer = setInterval(() => {
      now = Date.now();
    }, 60_000);
    return () => {
      clearInterval(timer);
      disposeSubs();
      clearProgress();
    };
  });

  async function refresh() {
    const sid = effectiveSport;
    if (!sid || busy) return;
    busy = true;
    error = '';
    try {
      const res = await startPredictorRefresh(sid, fromDay, true);
      if (!res.alreadyRunning) {
        run = {
          runId: res.runId,
          dayKey: fromDay,
          sportId: sid,
          progress: 0,
          stage: 'Queued',
          status: 'running',
          startedAt: Date.now(),
          updatedAt: Date.now()
        } as PredictorRun;
      }
    } catch (err: any) {
      error = String(err?.message || err);
    } finally {
      busy = false;
    }
  }

  function backHome() {
    void goto('/');
  }
</script>

<div class="predictor-root" style={`--accent:${accent}`}>
  {#if predictorLocked}
    <div class="paywall">
      <div class="paywall-card">
        <span class="pw-badge">Master Pass</span>
        <h2 class="pw-title">The AI Predictor is a Master Pass feature</h2>
        <p class="pw-copy">
          Eze Ugo &amp; the nine-agent team surface only matches clearing the {DEFAULT_CONFIDENCE_FLOOR}% Real
          Win Chance floor across 11 sports. Upgrade your monthly pass to unlock it.
        </p>
        <div class="pw-points">
          <span class="pw-point"><Check size={14} stroke-width={2.6} /> 60%+ Real Win Chance picks</span>
          <span class="pw-point"><Check size={14} stroke-width={2.6} /> 9 specialist AI agents</span>
          <span class="pw-point"><Check size={14} stroke-width={2.6} /> All 11 sports, refreshed nightly</span>
        </div>
        {#if !authState.isAuthenticated}
          <button class="cta pw-cta" type="button" onclick={() => void goto('/auth?mode=signup&redirect=checkout')}>
            <Wand2 size={15} stroke-width={2.4} />
            Sign in to upgrade
          </button>
          <p class="pw-hint">Already a Master member? Sign in with the account that purchased the pass.</p>
        {:else}
          <button class="cta pw-cta" type="button" onclick={() => void goto('/checkout?tier=master')}>
            <Wand2 size={15} stroke-width={2.4} />
            Upgrade to Master Pass — ₦10,000 / month
          </button>
        {/if}
      </div>
    </div>
  {:else}
  <div class="predictor-inner">
    <header class="predictor-head">
      <button class="icon-btn" aria-label="Back to sports selection" onclick={backHome} type="button">
        <ArrowLeft size={20} stroke-width={2.5} />
      </button>
      <div class="title-block">
        <span class="eyebrow">Eze Ugo &amp; the Agent Team</span>
        <h1>AI Predictor</h1>
        <div class="title-sport-ic" style={`color:${accent}`}>
          <PredictorSportIcon sport={effectiveSport} size={20} strokeWidth={2} />
        </div>
      </div>
      <button
        class="icon-btn refresh"
        aria-label="Refresh day cache"
        title="Refresh day cache"
        onclick={refresh}
        type="button"
        disabled={busy || isRunning || phase === 'analyzing'}
      >
        <span class:spin={busy || isRunning}><RefreshCw size={18} stroke-width={2.2} /></span>
      </button>
    </header>

    <PredictorTeamSelect active={sportId} {accent} />

    {#if loading}
      <div class="placeholder">
        <span class="ph-icon"><Activity size={22} stroke-width={1.8} /></span>
        Loading scheduled matches for the selected window…
      </div>
    {:else}
      <PredictorDateFilter bind:fromDay bind:toDay bind:timeBand />

      <div class="game-tabs" role="tablist" aria-label="Filter matches by status">
        <button
          class="game-tab {gameTab === 'upcoming' ? 'is-active' : ''}"
          type="button"
          role="tab"
          aria-selected={gameTab === 'upcoming'}
          onclick={() => (gameTab = 'upcoming')}
        >
          Upcoming
          <span class="tab-count">{tabCounts.upcoming}</span>
        </button>
        <button
          class="game-tab {gameTab === 'inplay' ? 'is-active' : ''}"
          type="button"
          role="tab"
          aria-selected={gameTab === 'inplay'}
          onclick={() => (gameTab = 'inplay')}
        >
          {#if tabCounts.inplay > 0}
            <span class="live-dot" aria-hidden="true"></span>
          {/if}
          In-Play
          <span class="tab-count">{tabCounts.inplay}</span>
        </button>
        <button
          class="game-tab {gameTab === 'finished' ? 'is-active' : ''}"
          type="button"
          role="tab"
          aria-selected={gameTab === 'finished'}
          onclick={() => (gameTab = 'finished')}
        >
          Finished
          <span class="tab-count">{tabCounts.finished}</span>
        </button>
      </div>

      <PredictorStatusBanner
        {day}
        progress={phase === 'analyzing' ? agentProgress : isRunning ? refreshProgress : day?.status === 'ready' ? 100 : 0}
        stage={phase === 'analyzing' ? agentStage : ''}
        running={phase === 'analyzing' || isRunning}
        error={error || runError}
      />

      {#if phase === 'select'}
        <div class="selection-bar">
          <div class="sel-row">
            <span class="summary-chip">
              <Check size={14} stroke-width={2.6} />
              {selectedIds.length} of {PREDICTOR_MAX_SELECTIONS} selected
            </span>
            {#if matches.length > 0}
              <span class="summary-chip muted">
                {matches.length} scheduled {effectiveSport === 'mma' ? 'bouts' : effectiveSport === 'tennis' || effectiveSport === 'rally' ? 'matches' : 'matches'}
              </span>
            {/if}
            <span class="sel-actions">
              {#if matches.length > 0}
                <button class="link-btn" type="button" onclick={selectAll}>
                  Select {Math.min(PREDICTOR_MAX_SELECTIONS, matches.length)}
                </button>
              {/if}
              <button class="link-btn" type="button" onclick={clearAll} disabled={selectedIds.length === 0}>Clear</button>
            </span>
          </div>

          {#if selectNotice}
            <p class="notice" role="status">{selectNotice}</p>
          {/if}

          <button class="cta analyze" type="button" onclick={analyzeSelected} disabled={selectedIds.length === 0}>
            <Wand2 size={15} stroke-width={2.4} />
            Analyse selected {selectedIds.length > 0 ? `(${selectedIds.length})` : ''}
          </button>
        </div>

        {#if windowDays.length > 0}
          {#each windowDays as dk (dk)}
            {@const dayMatches = byDay[dk] ?? []}
            <section class="day-group">
              <h2 class="day-title">
                <span class="day-name">{dk === today ? 'Today' : dayKeyLabel(dk)}</span>
                <span class="day-key">{dk}</span>
                {#if dayHasData(dk) && (dayMatches.length === 0 || timeBand !== 'all')}
                  <span class="day-badge has">{dayMatchCount[dk] ?? 0} cached</span>
                {/if}
                {#if dayMatches.length > 0}
                  <span class="day-badge">{dayMatches.length} shown</span>
                {/if}
              </h2>

              {#if dayMatches.length > 0}
                {#each Object.entries(groupByLeague(dayMatches)) as [league, group] (dk + ':' + league)}
                  <div class="league-group">
                    <h3 class="league-title">
                      <span class="league-name">{league}</span>
                      <span class="league-count">{group.length}</span>
                    </h3>
                    <div class="match-list">
                      {#each group as match (match.matchId)}
                        {@const res = analyzeMatch(match)}
                        <PredictorMatchCard
                          match={match}
                          analysis={res.analysis}
                          qualifying={res.qualifying}
                          insight={insightFor(match)}
                          expanded={expandedMatches[match.matchId] ?? false}
                          {accent}
                          selectable
                          selected={isSelected(match.matchId)}
                          inPlay={statusOf(match) === 'inplay'}
                          finished={statusOf(match) === 'finished'}
                          finalScore={match.finalScore ?? match.oddsSnapshot?.finalScore}
                          onSelect={() => toggleMatch(match)}
                          onClick={() => {
                            const nowOpen = !(expandedMatches[match.matchId] ?? false);
                            expandedMatches = { ...expandedMatches, [match.matchId]: nowOpen };
                            if (nowOpen) void revealMatch(match);
                          }}
                        />
                      {/each}
                    </div>
                  </div>
                {/each}
              {:else}
                <div class="day-empty">
                  <PredictorSportIcon sport={effectiveSport} size={22} strokeWidth={1.6} />
                  <span>
                    {timeBand !== 'all' && gameTab === 'upcoming'
                      ? 'No matches in this time band.'
                      : gameTab !== 'upcoming'
                        ? `No ${gameTab === 'inplay' ? 'in-play' : 'finished'} matches in this window.`
                        : dayHasData(dk)
                          ? 'No matches for this day in the cache.'
                          : 'No data cached for this day yet.'}
                  </span>
                  {#if !dayHasData(dk)}
                    <button class="day-refresh" type="button" onclick={() => refreshDay(dk)} disabled={busy || isRunning}>
                      Run agents
                    </button>
                  {/if}
                </div>
              {/if}
            </section>
          {/each}
        {:else}
          <div class="empty-state">
            <div class="empty-ic">
              <PredictorSportIcon sport={effectiveSport} size={34} strokeWidth={1.6} />
            </div>
            <p>No scheduled matches cached in the {fromDay}…{toDay} window.</p>
            {#if bootstrapMsg}
              <p class="bootstrap-msg" role="status">{bootstrapMsg}</p>
            {:else}
              <p class="hint">The agent team runs automatically three times daily. You can also load all sports right now.</p>
            {/if}
            <div class="empty-actions">
              <button class="cta" type="button" onclick={runBootstrapAll} disabled={busy || isRunning || bootstrapping}>
                <Zap size={15} stroke-width={2.4} />
                {bootstrapping ? 'Agents running…' : 'Load all sports now'}
              </button>
              <button class="cta secondary" type="button" onclick={refresh} disabled={busy || isRunning || bootstrapping}>Run {effectiveSport} only</button>
            </div>
          </div>
        {/if}
      {:else if phase === 'analyzing'}
        <div class="working">
          <p class="working-title">
            Eze Ugo &amp; team are preparing verdicts for your {results.length} selected match{results.length === 1 ? '' : 'es'}…
          </p>
          <p class="working-sub">
            Screening runs deterministically over the cached scopes — no network round-trip required.
          </p>
        </div>
      {:else}
        <div class="results-bar">
          <button
            class="icon-btn"
            aria-label="Back to match selection"
            title="Change selection"
            onclick={backToSelection}
            type="button"
          >
            <ChevronLeft size={20} stroke-width={2.5} />
          </button>
          <div class="results-meta">
            <span class="summary-chip">
              <Check size={14} stroke-width={2.6} />
              {results.length} match{results.length === 1 ? '' : 'es'} analysed
            </span>
            <span class="summary-chip">{qualifiedCount} over the {DEFAULT_CONFIDENCE_FLOOR}% floor</span>
            <span class="summary-chip muted"><Clock3 size={14} stroke-width={2.2} /> Cache: {fromDay}…{toDay}</span>
          </div>
          <button class="link-btn" type="button" onclick={backToSelection}>Change selection</button>
        </div>

        {#if results.length > 0}
          <div class="match-list">
            {#each results as r (r.match.matchId)}
              <PredictorMatchCard
                match={r.match}
                analysis={r.analysis}
                qualifying={r.qualifying}
                {accent}
                expanded
                inPlay={statusOf(r.match) === 'inplay'}
                finished={statusOf(r.match) === 'finished'}
                finalScore={r.match.finalScore ?? r.match.oddsSnapshot?.finalScore}
              />
              <PredictorVerdictPanel
                insight={r.insight ? (r.insight as import('$lib/cloudflareAi').AiAnalysisResult['insights']) : buildPredictorInsights(r.match, r.qualifying)}
                greatMindsDebate={r.greatMindsDebate}
                picks={r.qualifying}
                metrics={r.analysis?.metrics}
                {agentsRun}
                citations={sourcesUsed}
                {warnings}
                {accent}
                finalScore={r.match.finalScore ?? r.match.oddsSnapshot?.finalScore}
              />
            {/each}
          </div>
        {:else}
          <div class="empty-state">
            <div class="empty-ic"><Inbox size={30} stroke-width={1.8} /></div>
            <p>No matches were analysed.</p>
            <p class="hint">Go back and select at least one scheduled match to generate a verdict.</p>
            <button class="cta" type="button" onclick={backToSelection}>Select matches</button>
          </div>
        {/if}
      {/if}
    {/if}

    <DailyPnlSummary matches={matches} />

<footer class="predictor-foot">
      <p>
        Data refreshed nightly at 00:00 WAT (23:00 UTC) from betwatch.fr and cross-reference odds, betting and prediction registries.
        Select any scheduled match to run the agent team, which surfaces only selections that clear the
        {DEFAULT_CONFIDENCE_FLOOR}% Real Win Chance floor. All match times shown in West Africa Time (WAT, UTC+1). Always gamble responsibly.
      </p>
</footer>
  </div>
  {/if}
</div>

<style>
  .predictor-root { min-height: 100vh; background: var(--c-surface, #0b1120); }
  .predictor-inner { max-width: 680px; margin: 0 auto; padding: 14px 16px 40px; }

